param([string]$MsvcRoot,[string]$SdkRoot,[string]$SdkVersion,[string]$OutDir=(Join-Path $PSScriptRoot 'out'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$previous=Get-Content -Raw (Join-Path $PSScriptRoot '../r5-003/out/build.json')|ConvertFrom-Json
if(-not $MsvcRoot){$MsvcRoot=$previous.msvc};if(-not $SdkRoot){$SdkRoot=$previous.sdk};if(-not $SdkVersion){$SdkVersion=$previous.sdkVersion}
$OutDir=[IO.Path]::GetFullPath($OutDir);New-Item -ItemType Directory -Path $OutDir -Force|Out-Null
$compiler=Join-Path $MsvcRoot 'bin/Hostx64/x64/cl.exe';$oldPath=$env:PATH;$oldInclude=$env:INCLUDE;$oldLib=$env:LIB
try{
 $env:PATH="$(Split-Path $compiler);$oldPath";$env:INCLUDE=@((Join-Path $MsvcRoot 'include'),(Join-Path $SdkRoot "Include/$SdkVersion/ucrt"),(Join-Path $SdkRoot "Include/$SdkVersion/shared"),(Join-Path $SdkRoot "Include/$SdkVersion/um"))-join ';';$env:LIB=@((Join-Path $MsvcRoot 'lib/x64'),(Join-Path $SdkRoot "Lib/$SdkVersion/ucrt/x64"),(Join-Path $SdkRoot "Lib/$SdkVersion/um/x64"))-join ';'
 $reuse=@();foreach($name in @('fixture.exe','second.exe','helper.exe','runtime304.dll')){$source=Join-Path $PSScriptRoot "../r5-003/out/$name";$target=Join-Path $OutDir $name;$sha=(Get-FileHash $source).Hash.ToLowerInvariant();if(-not(Test-Path -LiteralPath $target) -or $sha -ne (Get-FileHash $target).Hash.ToLowerInvariant()){Copy-Item -LiteralPath $source -Destination $target -Force};if($sha -ne (Get-FileHash $target).Hash.ToLowerInvariant()){throw 'Reuse byte mismatch'};$reuse+=[ordered]@{file=$name;sha256=$sha;source=$source;identical=$true}}
 $reuse|ConvertTo-Json -Depth 5|Set-Content (Join-Path $OutDir 'reuse.json') -Encoding utf8
 $flags=@('/nologo','/std:c++20','/EHsc','/W4','/WX','/O2','/MT','/GS','/guard:cf','/Gy','/utf-8','/DUNICODE','/D_UNICODE','/D_WIN32_WINNT=0x0A00','/DFOCUS_VIEWS_CRASH_EXPERIMENT','/DFOCUS_VIEWS_STOPPOINT_EXPERIMENT','/Zi',"/Fd$(Join-Path $OutDir 'compiler.pdb')")
 $groups=[ordered]@{manager=@('../r5-004/manager_main.cpp');controller=@('../r5-004/controller.cpp');fixture=@('clients/fixture_client.cpp');recorder=@('clients/recorder_client.cpp');store=@('../r5-003/runtime/store.cpp');'abort-runtime'=@('abort-runtime.cpp');'abort-helper'=@('abort-helper.cpp')};$objects=@()
 foreach($group in $groups.Keys){$obj=Join-Path $OutDir ($group+'.obj');& $compiler @flags /c "/Fo$obj" (Join-Path $PSScriptRoot $groups[$group][0]);if($LASTEXITCODE -ne 0){throw "Compile failed $group"};$objects+= $obj}
 $kernel=@();$index=0;foreach($unit in @('../r5-001a/runtime/native.cpp','../r5-001a/runtime/codec.cpp','../r5-002/runtime/execution.cpp')){$obj=Join-Path $OutDir ("kernel-$index.obj");& $compiler @flags /c "/Fo$obj" (Join-Path $PSScriptRoot $unit);if($LASTEXITCODE -ne 0){throw "Compile failed $unit"};$kernel+=$obj;$index++}
 & (Join-Path $MsvcRoot 'bin/Hostx64/x64/lib.exe') /nologo "/OUT:$(Join-Path $OutDir 'kernel.lib')" @kernel;if($LASTEXITCODE -ne 0){throw 'Kernel archive failed'}
 $libs=@('user32.lib','gdi32.lib','ole32.lib','windowscodecs.lib','bcrypt.lib','imm32.lib','advapi32.lib')
 foreach($group in @('manager','controller','fixture','recorder','abort-runtime','abort-helper')){$dll=$group -in @('fixture','recorder','abort-runtime');$target=if($group -eq 'abort-runtime'){'abort-runtime.dll'}elseif($dll){$group+'-client.dll'}else{$group+'.exe'};$link=@('/nologo');if($dll){$link+='/LD'};$link+=@((Join-Path $OutDir ($group+'.obj')),(Join-Path $OutDir 'store.obj'),(Join-Path $OutDir 'kernel.lib'),"/Fe$(Join-Path $OutDir $target)");$link+=$libs;$link+=@('/link','/INCREMENTAL:NO','/DYNAMICBASE','/NXCOMPAT','/CETCOMPAT','/guard:cf','/DEBUG:FULL');& $compiler @link;if($LASTEXITCODE -ne 0){throw "Link failed $group"}}
 $sources=@('../r5-004/manager_main.cpp','../r5-004/controller.cpp','../r5-004/crash.hpp','clients/run.hpp','clients/fixture_client.cpp','clients/recorder_client.cpp','build.ps1','../r5-003/clients/restart.hpp','../r5-003/runtime/store.cpp','../r5-003/runtime/store.hpp','../r5-002/clients/host.hpp','../r5-002/runtime/experiment-points.hpp','../r5-002/runtime/processes.hpp','../r5-002/runtime/execution.cpp','../r5-002/runtime/execution.hpp','../r5-001a/runtime/native.cpp','../r5-001a/runtime/codec.cpp','stopped-cleanup.hpp','abort-host.hpp','abort-channel.hpp','abort-helper.cpp','abort-runtime.cpp','test.ps1','../r5-002/clients/fixture_model.hpp','../r5-002/clients/recorder_model.hpp')
 [ordered]@{time=(Get-Date -Format o);sourceHead=(& git -C $PSScriptRoot rev-parse HEAD);system=[Environment]::OSVersion.VersionString;msvc=$MsvcRoot;sdk=$SdkRoot;sdkVersion=$SdkVersion;compiler=(Get-Item $compiler).VersionInfo.FileVersion;security='/GS /guard:cf /CETCOMPAT';crashInstrumentation='opt-in stopped-checkpoint cleanup; old ABI and default path unchanged';sourceInputs=@($sources|ForEach-Object{[ordered]@{file=$_;sha256=(Get-FileHash (Join-Path $PSScriptRoot $_)).Hash.ToLowerInvariant()}});binaries=@(Get-ChildItem $OutDir -File|Where-Object Extension -in @('.exe','.dll','.lib')|ForEach-Object{[ordered]@{file=$_.Name;sha256=(Get-FileHash $_.FullName).Hash.ToLowerInvariant()}})}|ConvertTo-Json -Depth 7|Set-Content (Join-Path $OutDir 'build.json') -Encoding utf8
 Write-Output 'R5_004A_BUILD_OK'
}finally{$env:PATH=$oldPath;$env:INCLUDE=$oldInclude;$env:LIB=$oldLib}
